import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:rattil/core/align/aligner.dart';
import 'package:rattil/core/align/config.dart';
import 'package:rattil/core/align/models.dart';
import 'package:rattil/core/align/phonetics.dart';
import 'package:rattil/core/align/units.dart';

/// Per-word phonemes generated by quran-transcript (tool/spike/spike.py).
final Map<String, List<String>> ref = {
  for (final e in (jsonDecode(File('test/fixtures/reference_words.json').readAsStringSync()) as Map).entries)
    e.key as String: List<String>.from(e.value as List),
};

AlignmentResult run(List<String> words, String heard, {Map<int, List<String>>? variants}) =>
    Aligner(ExpectedStream(words), variants: variants).align(toUnits(heard));

List<WordStatus> statuses(AlignmentResult r) => [for (final w in r.words) w.status];

/// Replaces the first character of [kind] in [word] with [by].
String replaceFirst(String word, UnitKind kind, String by) {
  final chars = word.split('');
  final i = chars.indexWhere((c) => phoneticChars[c]?.kind == kind);
  chars[i] = by;
  return chars.join();
}

void main() {
  group('toUnits', () {
    test('groups runs and reads gemination and madd length', () {
      final u = toUnits('للَاااا');
      expect(u.map((x) => (x.kind, x.length)).toList(), [
        (UnitKind.consonant, 2),
        (UnitKind.shortVowel, 1),
        (UnitKind.longVowel, 4),
      ]);
      expect(u.first.isGeminated, isTrue);
    });

    test('qalqala becomes a detail of the consonant before it', () {
      final u = toUnits('دڇ');
      expect(u, hasLength(1));
      expect(u.single.details, {Detail.qalqala});
    });

    test('noon then noon mokhfah merge into one unit', () {
      final u = toUnits('نںں');
      expect(u.single.base, 'ن');
      expect(u.single.length, 3);
      expect(u.single.details, {Detail.ikhfa});
    });

    test('rejects unknown characters', () {
      expect(() => toUnits('x'), throwsA(isA<UnknownPhonemeError>()));
    });
  });

  group('ExpectedStream', () {
    test('maps every unit to its word', () {
      final s = ExpectedStream(ref['1:1']!);
      expect(s.wordCount, 4);
      expect(s.wordStart(0), 0);
      expect(s.wordEnd(3), s.units.length);
      for (var w = 0; w < 4; w++) {
        expect(s.wordEnd(w), greaterThan(s.wordStart(w)));
      }
    });

    test('a same-letter idgham run belongs to the first word', () {
      // Synthetic: word A ends in lam, word B starts with lam.
      final s = ExpectedStream(['قُل', 'لَاا']);
      expect(s.units[2].length, 2);
      expect(s.unitWord[2], 0);
      expect(s.wordStart(1), 3);
      final r = Aligner(s).align(toUnits('قُللَاا'));
      expect(statuses(r), [WordStatus.correct, WordStatus.correct]);
    });
  });

  group('Aligner on real reference phonemes', () {
    for (final key in ref.keys) {
      test('$key read correctly gives no issues', () {
        final r = run(ref[key]!, ref[key]!.join());
        expect(statuses(r), everyElement(WordStatus.correct));
        expect(r.words.expand((w) => w.issues), isEmpty);
        expect(r.extras, isEmpty);
      });
    }

    test('skipped word', () {
      final w = ref['1:7']!;
      final r = run(w, [...w.take(3), ...w.skip(4)].join());
      expect(r.words[3].status, WordStatus.skipped);
      expect(r.words[3].hasHigh, isTrue);
      expect([...statuses(r).take(3), ...statuses(r).skip(4)], everyElement(WordStatus.correct));
    });

    test('extra word between two words', () {
      final w = ref['1:7']!;
      final extra = ref['112:1']![0];
      final r = run(w, [...w.take(2), extra, ...w.skip(2)].join());
      expect(r.extras, hasLength(1));
      expect(r.extras.single.beforeWord, 2);
      expect(statuses(r), everyElement(WordStatus.correct));
    });

    test('wrong letter is high and marks the word wrong', () {
      final w = [...ref['1:7']!];
      final heard = [...w]..[4] = replaceFirst(w[4], UnitKind.consonant, 'ز');
      final r = run(w, heard.join());
      expect(r.words[4].status, WordStatus.wrong);
      expect(r.words[4].issues.map((i) => i.type), contains(IssueType.wrongLetter));
      expect(r.words.where((x) => x.word != 4).map((x) => x.status), everyElement(WordStatus.correct));
    });

    test('confusable letter swap is unsure, not wrong', () {
      final w = ['سَبَاا', ...ref['112:1']!];
      final heard = ['ثَبَاا', ...ref['112:1']!];
      final r = run(w, heard.join());
      expect(r.words[0].status, WordStatus.unsure);
      expect(r.words[0].issues.single.unsure, isTrue);
    });

    test('wrong harakah is medium: orange mark, word still correct', () {
      final w = ref['112:1']!;
      final first = w[0];
      final vowel = first.split('').firstWhere((c) => phoneticChars[c]?.kind == UnitKind.shortVowel);
      final other = vowel == 'َ' ? 'ِ' : 'َ';
      final heard = [replaceFirst(first, UnitKind.shortVowel, other), ...w.skip(1)];
      final r = run(w, heard.join());
      expect(r.words[0].status, WordStatus.correct);
      expect(r.words[0].hasMedium, isTrue);
      expect(r.words[0].hasHigh, isFalse);
    });

    test('shorter madd is a low hint only', () {
      final w = ref['1:1']!;
      final last = w[3]; // ends in a 4-count yaa madd
      final heard = [...w.take(3), last.replaceAll('ۦۦۦۦ', 'ۦۦ')];
      final r = run(w, heard.join());
      expect(r.words[3].status, WordStatus.correct);
      expect(r.words[3].issues.map((i) => i.type), [IssueType.maddLength]);
    });

    test('repeating words is not a mistake', () {
      final w = ref['1:7']!;
      final r = run(w, [w[0], w[1], w[2], w[1], w[2], ...w.skip(3)].join());
      expect(statuses(r), everyElement(WordStatus.correct));
      expect(r.extras, isEmpty);
    });

    test('repeating to fix a mistake keeps the last attempt', () {
      final w = ref['1:7']!;
      final bad = replaceFirst(w[1], UnitKind.consonant, 'ز');
      final r = run(w, [w[0], bad, w[1], ...w.skip(2)].join());
      expect(statuses(r), everyElement(WordStatus.correct));
    });

    test('stopping mid-ayah leaves later words pending', () {
      final w = ref['1:7']!;
      final r = run(w, w.take(5).join());
      expect(statuses(r).take(5), everyElement(WordStatus.correct));
      expect(statuses(r).skip(5), everyElement(WordStatus.pending));
      expect(r.words[0].isPast, isTrue);
      expect(r.words[4].isPast, isFalse);
    });

    test('a half-said word is pending, not wrong', () {
      final w = ref['1:7']!;
      final half = w[3].substring(0, w[3].length ~/ 2);
      final r = run(w, [...w.take(3), half].join());
      expect(r.words[3].status, WordStatus.pending);
    });

    test('noise before the first word is ignored', () {
      final w = ref['112:1']!;
      final r = run(w, 'شُش${w.join()}');
      expect(statuses(r), everyElement(WordStatus.correct));
    });

    test('swapped words are caught', () {
      final w = ref['1:7']!;
      final r = run(w, [w[0], w[2], w[1], ...w.skip(3)].join());
      final bad = r.words.where((x) => x.hasHigh).length + r.extras.length;
      expect(bad, greaterThan(0));
    });

    test('a wasl variant is accepted at an ayah boundary', () {
      // Synthetic, not Quran text: the waqf form ends in a sakin consonant;
      // the wasl form adds a vowel and a noon (tanween) before the next ayah.
      final waqf = ['بَتَث'];
      final wasl = 'بَتَثُن';
      final next = ['مَاا'];
      final words = [...waqf, ...next];
      final heardWasl = wasl + next.join();
      final plain = run(words, heardWasl);
      expect(plain.words[0].hasHigh, isTrue, reason: 'without the variant the noon is an extra letter');
      final withVariant = run(words, heardWasl, variants: {0: [wasl]});
      expect(withVariant.words[0].status, WordStatus.correct);
      expect(withVariant.words[0].hasHigh, isFalse);
    });

    test('window alignment reports global word and unit indices', () {
      final w = ref['1:7']!;
      final s = ExpectedStream(w);
      final r = Aligner(s).align(toUnits(w.skip(4).take(2).join()), fromWord: 4, toWord: 8);
      expect(r.words.map((x) => x.word), [4, 5, 6, 7]);
      expect(statuses(r).take(2), everyElement(WordStatus.correct));
      expect(r.endUnit, s.wordEnd(5));
    });

    test('tail cost is low when on track and high on unrelated speech', () {
      final w = ref['1:7']!;
      final onTrack = run(w, w.take(4).join());
      expect(onTrack.tailCostPerUnit, lessThan(0.1));
      final lost = run(w, w.take(2).join() + ref['2:255']!.skip(10).take(4).join());
      expect(lost.tailCostPerUnit, greaterThanOrEqualTo(const TeacherConfig().jumpTailCost));
    });
  });
}
